import type { Metadata } from "next";
import Image from "next/image";

import { PageHero } from "@/components/PageHero";
import { Reveal } from "@/components/Reveal";
import { LocationCard } from "@/components/LocationCard";
import { SectionTitle } from "@/components/SectionTitle";
import { CtaBand } from "@/components/CtaBand";

import { getContent } from "@/lib/i18n";
import { heroImages, salonImages } from "@/lib/images";
import { site } from "@/lib/site";

const t = getContent();
const s = t.salon;

export const metadata: Metadata = {
  title: `${s.title} – Zouk Mikael, Jounieh & Germany`,
  description: s.description,

  alternates: {
    canonical: "/hair-salon",
  },

  openGraph: {
    title: `${s.title} | Salon Alain`,
    description: s.description,
    url: "/hair-salon",
  },
};

/*
  Rotation correction for each salon photo.

  0 = first image
  1 = second image
  etc.

  If one photo is still facing the wrong direction:
  change 90 to -90 or -90 to 90.
*/
const salonImageRotation = [
  -90, // image 1
  90,  // image 2
  90,  // image 3
  -90, // image 4
  0,   // image 5 - already correct
  90,  // image 6
];

export default function HairSalonPage() {
  return (
    <>
      {/* HERO */}
      <PageHero
        kicker={s.title}
        title={s.heading}
        subtitle={s.subtitle}
        image={heroImages.salon}
        variant="band"
      />

      {/* INTRO */}
      <section className="py-20 sm:py-28">
        <div className="container-page grid gap-12 lg:grid-cols-12">

          <Reveal className="lg:col-span-4">
            <p className="font-serif text-3xl font-medium leading-tight text-plum-700">
              “{s.pullQuote}”
            </p>
          </Reveal>

          <Reveal
            delay={120}
            className="space-y-5 text-[1.02rem] leading-[1.8] text-ink/80 lg:col-span-7 lg:col-start-6"
          >
            <p className="dropcap">
              {s.intro[0]}
            </p>

            <p>
              {s.intro[1]}
            </p>
          </Reveal>

        </div>
      </section>

      {/* EXPERIENCE */}
      <section className="bg-plum-50/70 py-20 sm:py-28">

        <div className="container-page">

          <SectionTitle
            title={s.experience.title}
            align="center"
          />

          <ol className="mx-auto mt-14 grid max-w-5xl gap-10 sm:grid-cols-2 lg:grid-cols-4">

            {s.experience.items.map((it, i) => (
              <Reveal
                as="li"
                key={it.title}
                delay={i * 90}
                className="border-t border-plum-700 pt-5"
              >
                <span className="font-serif text-sm italic text-plum-500">
                  {String(i + 1).padStart(2, "0")}
                </span>

                <h3 className="mt-2 font-serif text-2xl font-medium">
                  {it.title}
                </h3>

                <p className="mt-3 text-[0.95rem] leading-relaxed text-ink/75">
                  {it.desc}
                </p>
              </Reveal>
            ))}

          </ol>

        </div>

      </section>

      {/* PROFESSIONAL SALON GALLERY */}
      <section className="py-20 sm:py-28">

        <div className="container-page">

          <SectionTitle
            title={s.galleryTitle}
            align="center"
          />

          <Reveal className="mt-14">

            <div className="grid grid-cols-1 gap-5 md:grid-cols-2 lg:grid-cols-12 lg:gap-6">

              {salonImages.map((image, index) => {

                const rotation =
                  salonImageRotation[index] ?? 0;

                /*
                  Makes the first image large,
                  then creates a more editorial / luxury layout.
                */
                const layout =
                  index === 0
                    ? "lg:col-span-7 lg:row-span-2"
                    : index === 1
                    ? "lg:col-span-5"
                    : index === 2
                    ? "lg:col-span-5"
                    : index === 3
                    ? "lg:col-span-4"
                    : index === 4
                    ? "lg:col-span-4"
                    : "lg:col-span-4";

                const height =
                  index === 0
                    ? "h-[420px] sm:h-[560px] lg:h-[720px]"
                    : "h-[350px] sm:h-[430px] lg:h-[350px]";

                return (
                  <div
                    key={image.src}
                    className={`${layout} ${height} group relative overflow-hidden rounded-[26px] bg-plum-50`}
                  >
                    <Image
                      src={image.src}
                      alt={image.alt}
                      fill
                      sizes="
                        (max-width: 768px) 100vw,
                        (max-width: 1024px) 50vw,
                        40vw
                      "
                      className="
                        object-cover
                        object-center
                        transition-transform
                        duration-700
                        ease-out
                        group-hover:scale-[1.03]
                      "
                      style={{
                        transform:
                          rotation === 0
                            ? undefined
                            : `rotate(${rotation}deg) scale(1.45)`,
                      }}
                    />

                    {/* Elegant subtle overlay */}
                    <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/10 via-transparent to-transparent" />

                  </div>
                );
              })}

            </div>

          </Reveal>

        </div>
      </section>

      {/* LOCATIONS */}
      <section className="border-t border-plum-200/70 py-20 sm:py-28">

        <div className="container-page">

          <SectionTitle
            title={s.locationsTitle}
            align="center"
          />

          <div className="mt-14 grid gap-14 lg:grid-cols-2 lg:gap-20">

            {site.locations.map((loc, i) => (
              <Reveal
                key={loc.id}
                delay={i * 100}
              >
                <LocationCard location={loc} />
              </Reveal>
            ))}

          </div>

        </div>

      </section>

      <CtaBand />
    </>
  );
}
